import openpyxl

wb = openpyxl.load_workbook('gdp.xlsx')
sheet = wb['Task']

print("Searching for years (2018-2025) in Task sheet:")
found_year = False
for r in range(1, 20):
    for c in range(1, 20):
        val = sheet.cell(row=r, column=c).value
        if val and isinstance(val, (int, float, str)) and str(val).startswith('20'):
             # Check if it looks like a year
             try:
                 year_val = int(str(val).split('.')[0])
                 if 2000 < year_val < 2030:
                     print(f"Found {val} at Row {r}, Col {c}")
                     found_year = True
             except:
                 pass
if not found_year:
    print("No obvious years found in top 20x20.")

print("\nChecking Stats Labels (Rows 40-52, Cols C-E):")
for r in range(40, 53):
    vals = [sheet.cell(row=r, column=c).value for c in range(3, 7)]
    print(f"Row {r}: {vals}")
